@font-face{font-family:Bungee;src:url('./fonts/Bungee-Regular.ttf') format('truetype');font-display:swap}
@font-face{font-family:Nunito;src:url('./fonts/Nunito-Medium.ttf') format('truetype');font-weight:500;font-display:swap}
@font-face{font-family:Nunito;src:url('./fonts/Nunito-Bold.ttf') format('truetype');font-weight:700;font-display:swap}
@font-face{font-family:Nunito;src:url('./fonts/Nunito-ExtraBold.ttf') format('truetype');font-weight:800;font-display:swap}
@font-face{font-family:Nunito;src:url('./fonts/Nunito-Black.ttf') format('truetype');font-weight:900;font-display:swap}

:root{
  --ink:#10221a;
  --ink-2:#17352a;
  --cream:#fff8e8;
  --cream-2:#f6edda;
  --muted:#b8c9bb;
  --green:#b8f36b;
  --green-2:#7cdc52;
  --gold:#ffd166;
  --coral:#ff8b6a;
  --cyan:#79eee2;
  --glass:rgba(12,31,24,.66);
  --glass-2:rgba(18,43,33,.82);
  --line:rgba(255,255,255,.16);
  --safe-top:env(safe-area-inset-top,0px);
  --safe-bottom:env(safe-area-inset-bottom,0px);
  --safe-left:env(safe-area-inset-left,0px);
  --safe-right:env(safe-area-inset-right,0px);
  --ease:cubic-bezier(.2,.8,.2,1);
}

*{box-sizing:border-box}
html,body{height:100%;margin:0;overflow:hidden;background:#0c1d16}
body{
  font-family:Nunito,system-ui,sans-serif;color:var(--cream);
  -webkit-tap-highlight-color:transparent;user-select:none;-webkit-user-select:none;
  overscroll-behavior:none;touch-action:none;
}
button{font:inherit;color:inherit;border:0;background:none;padding:0;cursor:pointer;touch-action:manipulation}
button:focus-visible{outline:2px solid var(--cyan);outline-offset:3px}
#app{position:fixed;inset:0;overflow:hidden;isolation:isolate}

.sky{
  position:absolute;inset:0;z-index:-3;
  background:
    radial-gradient(ellipse 55% 45% at 76% 12%,rgba(255,244,195,.88),transparent 60%),
    radial-gradient(ellipse 70% 55% at 25% 30%,rgba(137,222,255,.48),transparent 65%),
    linear-gradient(180deg,#2e7fab 0%,#69bdd9 27%,#b8e2e4 54%,#f6e6c7 76%,#e5c797 100%);
}
.sun-haze{
  position:absolute;inset:0;z-index:1;pointer-events:none;
  background:radial-gradient(circle at 76% 13%,rgba(255,248,207,.28),transparent 24%);
  mix-blend-mode:screen;
}
#scene{position:absolute;inset:0;width:100%;height:100%;display:block;z-index:0;touch-action:none}
.vignette{
  position:absolute;inset:0;z-index:2;pointer-events:none;
  background:radial-gradient(ellipse 95% 85% at 50% 44%,transparent 45%,rgba(4,16,11,.34) 100%);
}
.grain{
  position:absolute;inset:-50%;z-index:3;pointer-events:none;opacity:.06;
  background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.55'/%3E%3C/svg%3E");
  animation:grainShift .9s steps(2) infinite;
}
@keyframes grainShift{0%{transform:translate(0,0)}25%{transform:translate(-2%,1%)}50%{transform:translate(1%,-2%)}75%{transform:translate(2%,2%)}100%{transform:translate(-1%,-1%)}}

/* ---------- shared HUD ---------- */
.hud-panel{
  background:linear-gradient(145deg,rgba(21,48,37,.86),rgba(9,26,20,.72));
  border:1px solid var(--line);
  box-shadow:0 18px 45px rgba(2,13,9,.32),inset 0 1px 0 rgba(255,255,255,.08);
  backdrop-filter:blur(16px) saturate(120%);-webkit-backdrop-filter:blur(16px) saturate(120%);
}
.panel-label{
  font-size:10px;font-weight:900;letter-spacing:.17em;color:#cfe2d0;
  display:flex;align-items:center;gap:7px;text-transform:uppercase;
}
.live-dot{width:6px;height:6px;border-radius:50%;background:var(--green);box-shadow:0 0 9px var(--green);animation:pulseDot 2.2s infinite}
@keyframes pulseDot{0%,100%{opacity:1}50%{opacity:.4}}

.topbar{
  position:absolute;z-index:20;top:calc(14px + var(--safe-top));left:calc(20px + var(--safe-left));right:calc(20px + var(--safe-right));
  display:flex;align-items:center;justify-content:space-between;gap:18px;
  opacity:0;transform:translateY(-12px);pointer-events:none;transition:opacity .45s var(--ease),transform .45s var(--ease);
}
body.in-game .topbar{opacity:1;transform:none;pointer-events:auto}
.brand{display:flex;align-items:center;gap:11px;filter:drop-shadow(0 3px 10px rgba(0,0,0,.25))}
.brand-cube{width:34px;height:36px;position:relative;flex:none}
.cube-top,.cube-left,.cube-right{position:absolute;display:block}
.cube-top{width:24px;height:13px;left:5px;top:0;background:#d9ff8e;clip-path:polygon(50% 0,100% 50%,50% 100%,0 50%)}
.cube-left{width:14px;height:24px;left:0;top:10px;background:#7dcc53;clip-path:polygon(0 0,100% 22%,100% 100%,0 78%)}
.cube-right{width:14px;height:24px;right:0;top:10px;background:#4fa53c;clip-path:polygon(0 22%,100% 0,100% 78%,0 100%)}
.brand-type h1{font-family:Bungee,Impact,sans-serif;font-size:19px;letter-spacing:.04em;line-height:1;margin:0;color:#fff9e8;text-shadow:0 2px 0 rgba(20,54,36,.7)}
.brand-type p{font-size:8px;font-weight:900;letter-spacing:.28em;margin:4px 0 0;color:#b8e8c7}

.scoreboard{
  display:flex;align-items:center;gap:22px;padding:9px 20px;border-radius:16px;
  background:rgba(9,29,21,.48);border:1px solid rgba(255,255,255,.12);
  backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);box-shadow:0 10px 30px rgba(2,13,9,.22);
}
.score-item{display:flex;flex-direction:column;align-items:center;min-width:55px}
.score-item span{font-size:8px;font-weight:900;letter-spacing:.2em;color:#a8c4b0}
.score-item strong{font-family:Bungee,Impact,sans-serif;font-size:19px;line-height:1.2;color:#fff8e5;text-shadow:0 2px 0 rgba(0,0,0,.2);font-variant-numeric:tabular-nums}
.score-divider{width:1px;height:26px;background:rgba(255,255,255,.13)}
.top-actions{display:flex;gap:8px}
.icon-btn{
  width:40px;height:40px;border-radius:12px;display:grid;place-items:center;
  background:rgba(10,31,23,.5);border:1px solid rgba(255,255,255,.14);backdrop-filter:blur(10px);
  transition:transform .2s var(--ease),background .2s;
}
.icon-btn:hover{background:rgba(39,81,59,.72);transform:translateY(-1px)}
.icon-btn:active{transform:scale(.94)}
.icon-btn svg{width:20px;height:20px;fill:none;stroke:#e8f7e9;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.icon-btn .ico{fill:none}
.icon-btn .ico path:first-child{fill:#e8f7e9;stroke:none}
.icon-btn .ico .wave{fill:none;stroke:#e8f7e9}
.icon-btn .ico-muted{display:none}
body.muted .ico-sound{display:none}
body.muted .ico-muted{display:block}

/* ---------- build progress ---------- */
.build-panel{
  position:absolute;z-index:18;left:calc(22px + var(--safe-left));bottom:calc(24px + var(--safe-bottom));
  width:270px;border-radius:18px;padding:15px 16px 14px;
  opacity:0;transform:translateY(16px);pointer-events:none;transition:opacity .5s var(--ease),transform .5s var(--ease);
}
body.in-game .build-panel{opacity:1;transform:none;pointer-events:auto}
.build-top{display:flex;justify-content:space-between;align-items:flex-end;gap:8px;margin:10px 0 11px}
.build-name{font-weight:900;font-size:15px;letter-spacing:.01em;color:#fff8e7;line-height:1.1}
.build-sub{font-size:9.5px;color:#9fb8a7;margin-top:4px;line-height:1.2}
.build-pct{font-family:Bungee,Impact,sans-serif;font-size:21px;color:var(--green);text-shadow:0 0 18px rgba(184,243,107,.3);line-height:1}
.progress-track{height:9px;background:rgba(4,15,10,.55);border-radius:10px;overflow:hidden;position:relative;border:1px solid rgba(255,255,255,.08);box-shadow:inset 0 2px 5px rgba(0,0,0,.35)}
.progress-track i{display:block;height:100%;width:0;background:linear-gradient(90deg,#6dcc53,#b8f36b 55%,#e4ffa2);border-radius:10px;box-shadow:0 0 12px rgba(184,243,107,.55);transition:width .8s var(--ease);position:relative;z-index:1}
.progress-shine{position:absolute;inset:0;background:linear-gradient(100deg,transparent 20%,rgba(255,255,255,.4) 50%,transparent 80%);transform:translateX(-120%);animation:shine 3.5s 1s infinite;z-index:2}
@keyframes shine{0%,60%{transform:translateX(-120%)}85%,100%{transform:translateX(120%)}}
.build-pips{display:flex;gap:3px;margin-top:9px}
.build-pips i{height:4px;flex:1;border-radius:2px;background:rgba(255,255,255,.13);transition:background .4s,box-shadow .4s}
.build-pips i.on{background:#b8f36b;box-shadow:0 0 6px rgba(184,243,107,.55)}

/* ---------- next / hold ---------- */
.piece-stack{
  position:absolute;z-index:18;right:calc(22px + var(--safe-right));top:calc(88px + var(--safe-top));
  display:flex;flex-direction:column;gap:10px;width:148px;
  opacity:0;transform:translateX(16px);pointer-events:none;transition:opacity .5s var(--ease),transform .5s var(--ease);
}
body.in-game .piece-stack{opacity:1;transform:none;pointer-events:auto}
.piece-panel{border-radius:16px;padding:11px 12px 12px}
.mini-grid{display:grid;grid-template-columns:repeat(4,1fr);grid-auto-rows:1fr;gap:3px;margin-top:9px;height:62px;align-content:center}
.mini-grid i{border-radius:3px;background:transparent;box-shadow:none}
.mini-grid i.fill{box-shadow:inset 0 -2px 0 rgba(0,0,0,.2),inset 0 1px 0 rgba(255,255,255,.28),0 2px 5px rgba(0,0,0,.18)}
.mini-grid.hold-empty{position:relative}
.hold-panel{opacity:.92}
.key-hint{margin-left:auto;border:1px solid rgba(255,255,255,.18);border-radius:4px;padding:1px 4px;font-size:8px;color:#9eb6a5}

/* ---------- popups ---------- */
.combo-pop{
  position:absolute;z-index:30;left:50%;top:28%;transform:translate(-50%,0) scale(.7);opacity:0;text-align:center;pointer-events:none;
  transition:opacity .22s,transform .34s var(--ease);filter:drop-shadow(0 8px 20px rgba(0,0,0,.28));
}
.combo-pop.show{opacity:1;transform:translate(-50%,-16px) scale(1)}
.combo-pop b{display:block;font-family:Bungee,Impact,sans-serif;font-size:38px;letter-spacing:.02em;color:#fff;text-shadow:0 4px 0 #4c9f3d,0 0 24px rgba(184,243,107,.8);-webkit-text-stroke:1px rgba(21,53,30,.4)}
.combo-pop span{display:block;font-weight:900;color:var(--gold);font-size:16px;letter-spacing:.08em;margin-top:2px}
.toast{
  position:absolute;z-index:31;left:50%;top:calc(94px + var(--safe-top));transform:translate(-50%,-12px);opacity:0;
  display:flex;align-items:center;gap:9px;padding:9px 16px 9px 11px;border-radius:30px;
  background:rgba(11,36,25,.82);border:1px solid rgba(184,243,107,.32);box-shadow:0 12px 32px rgba(0,0,0,.28),0 0 24px rgba(184,243,107,.12);
  backdrop-filter:blur(12px);font-weight:800;font-size:12px;letter-spacing:.03em;transition:opacity .3s,transform .4s var(--ease);pointer-events:none;
}
.toast.show{opacity:1;transform:translate(-50%,0)}
.toast-icon{width:22px;height:22px;display:grid;place-items:center;border-radius:50%;background:var(--green);color:#17331c;font-size:12px;box-shadow:0 0 12px rgba(184,243,107,.45)}

/* ---------- touch controls ---------- */
.touch-controls{
  position:absolute;z-index:22;left:calc(16px + var(--safe-left));right:calc(16px + var(--safe-right));bottom:calc(14px + var(--safe-bottom));
  display:none;justify-content:space-between;align-items:flex-end;gap:12px;
  opacity:0;transform:translateY(18px);pointer-events:none;transition:opacity .4s,transform .4s var(--ease);
}
body.in-game .touch-controls{opacity:1;transform:none;pointer-events:auto}
.touch-cluster{display:flex;align-items:center;gap:8px}
.touch-btn{
  height:54px;min-width:54px;padding:0 15px;border-radius:16px;display:flex;align-items:center;justify-content:center;
