  backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);transition:transform .12s,background .12s;
  touch-action:none;
}
.touch-btn:active,.touch-btn.pressed{transform:scale(.92);background:rgba(79,145,80,.9)}
.touch-btn svg{width:25px;height:25px;fill:none;stroke:#f5ffef;stroke-width:2.1;stroke-linecap:round;stroke-linejoin:round}
.touch-btn.round{width:54px;min-width:54px;padding:0;border-radius:50%}
.touch-btn.rotate{border-color:rgba(121,238,226,.36);box-shadow:0 8px 20px rgba(0,0,0,.28),0 0 18px rgba(121,238,226,.1),inset 0 1px 0 rgba(255,255,255,.12)}
.touch-btn.drop{
  height:54px;border-radius:18px;padding:0 18px 0 16px;gap:9px;flex-direction:column;
