.touch-btn.drop svg{width:19px;height:19px;stroke:#17391d;margin-top:-5px}
@media (hover:none),(pointer:coarse){.touch-controls{display:flex}.key-hint{display:none}}
@media (max-width:700px){.touch-controls{display:flex}}

/* ---------- overlays / menu ---------- */
.overlay{position:absolute;inset:0;z-index:60;display:flex;align-items:center;justify-content:center;padding:24px}
.overlay.hidden{display:none}
.menu-overlay{
  z-index:50;align-items:flex-end;padding:24px 24px calc(6vh + var(--safe-bottom));
  background:linear-gradient(180deg,rgba(4,20,14,.02) 0%,rgba(4,20,14,0) 35%,rgba(4,20,14,.25) 56%,rgba(3,17,12,.82) 100%);
  transition:opacity .65s var(--ease),visibility .65s;
}
