.hero-title{font-family:Bungee,Impact,sans-serif;margin:13px 0 12px;display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:.18em;line-height:.88;letter-spacing:-.015em;font-size:clamp(36px,6.1vw,74px);color:#fff8e5;text-shadow:0 5px 0 #3d6e39,0 9px 22px rgba(0,0,0,.3)}
