    if (x > 0.8 && x < 11.3 && z > -6.5 && z < 6.4) continue;
    if (Math.hypot(x + 12.3, z - 6.4) < 4.1) continue;
    if (Math.abs(x - 6.2) < 1.2 && z > 3 && z < 11) continue;
    spots.push([x, z]);
