    post.castShadow = true;
    root.add(post);
  }

  // fireflies
  const count = 48;
  const fpos = new Float32Array(count * 3);
  const bases = [];
  for (let i = 0; i < count; i++) {
    const a = Math.random() * Math.PI * 2;
    const r = 3 + Math.random() * 9;
    const x = 6 + Math.cos(a) * r;
