669: class ParticleField {
670:   constructor(scene, max, opts = {}) {
671:     this.max = max;
672:     this.parts = [];
673:     this.cursor = 0;
674:     const pos = new Float32Array(max * 3);
675:     const col = new Float32Array(max * 3);
676:     for (let i = 0; i < max; i++) pos[i * 3 + 1] = -999;
677:     const geo = new THREE.BufferGeometry();
678:     geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
679:     geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
680:     this.geometry = geo;
681:     const mat = new THREE.PointsMaterial({
682:       size: opts.size ?? 0.16,
683:       map: opts.map ?? glowTexture,
684:       vertexColors: true,
685:       transparent: true,
686:       opacity: opts.opacity ?? 1,
687:       depthWrite: false,
688:       blending: opts.blending ?? THREE.AdditiveBlending,
689:       sizeAttenuation: true
690:     });
691:     this.points = new THREE.Points(geo, mat);
692:     this.points.frustumCulled = false;
693:     this.points.renderOrder = 5;
694:     scene.add(this.points);
695:     this.gravity = opts.gravity ?? -5;
696:     this.drag = opts.drag ?? 0.985;
697:   }
698: 
699:   burst(position, color, count = 22, opts = {}) {
700:     const speed = opts.speed ?? 3.2;
701:     const life = opts.life ?? 0.9;
702:     const spread = opts.spread ?? 0.3;
703:     const c = new THREE.Color(color);
704:     for (let i = 0; i < count; i++) {
705:       const idx = this.cursor++ % this.max;
706:       const p = this.parts[idx] || (this.parts[idx] = { pos: new THREE.Vector3(), vel: new THREE.Vector3(), life: 0, max: 1, color: new THREE.Color() });
707:       p.pos.copy(position).add(new THREE.Vector3((Math.random() - 0.5) * spread, (Math.random() - 0.5) * spread, (Math.random() - 0.5) * spread));
708:       const theta = Math.random() * Math.PI * 2;
709:       const phi = Math.random() * Math.PI;
710:       const s = speed * (0.35 + Math.random() * 0.8);
711:       p.vel.set(Math.sin(phi) * Math.cos(theta) * s, Math.cos(phi) * s * 0.8 + (opts.up ?? 1.4), Math.sin(phi) * Math.sin(theta) * s);
712:       p.life = p.max = life * (0.6 + Math.random() * 0.7);
713:       p.color.copy(c).offsetHSL((Math.random() - 0.5) * 0.06, 0, (Math.random() - 0.5) * 0.16);
714:       p.gravity = opts.gravity ?? this.gravity;
715:     }
716:   }
717: 
718:   update(dt) {
719:     const pos = this.geometry.attributes.position.array;
720:     const col = this.geometry.attributes.color.array;
721:     for (let i = 0; i < this.max; i++) {
722:       const p = this.parts[i];
723:       if (!p || p.life <= 0) {
724:         pos[i * 3 + 1] = -999;
725:         col[i * 3] = col[i * 3 + 1] = col[i * 3 + 2] = 0;
726:         continue;
727:       }
728:       p.life -= dt;
729:       p.vel.y += p.gravity * dt;
730:       p.vel.multiplyScalar(Math.pow(this.drag, dt * 60));
731:       p.pos.addScaledVector(p.vel, dt);
732:       const t = clamp(p.life / p.max, 0, 1);
733:       pos[i * 3] = p.pos.x;
734:       pos[i * 3 + 1] = p.pos.y;
735:       pos[i * 3 + 2] = p.pos.z;
736:       col[i * 3] = p.color.r * t;
737:       col[i * 3 + 1] = p.color.g * t;
738:       col[i * 3 + 2] = p.color.b * t;
739:     }
740:     this.geometry.attributes.position.needsUpdate = true;
741:     this.geometry.attributes.color.needsUpdate = true;
742:   }
743: }
