787:       const cell = state.cells[y][x];
788:       if (!cell) continue;
789:       const type = cell.type;
790:       let scale = 1;
791:       let lift = 0;
792:       let spin = 0;
793:       if (cell.clearStart != null) {
794:         const t = clamp((now - cell.clearStart) / 0.34, 0, 1);
795:         scale = 1 - t * 0.94;
796:         lift = t * 0.9;
797:         spin = t * 1.5;
798:       }
799:       dummy.position.set(x - (W - 1) / 2, y + 0.5 + lift, 0);
800:       dummy.rotation.set(0, spin, 0);
801:       dummy.scale.setScalar(scale * 0.995);
802:       dummy.updateMatrix();
803:       const idx = counts[type]++;
804:       boardMeshes[type].setMatrixAt(idx, dummy.matrix);
805:     }
806:   }
807:   for (const type of Object.keys(PIECE_COLORS)) {
808:     boardMeshes[type].count = counts[type];
809:     boardMeshes[type].instanceMatrix.needsUpdate = true;
810:   }
811: }
812: 
813: function updateActive() {
814:   const p = state.piece;
815:   for (const m of activeMeshes) m.visible = false;
816:   for (const g of ghostMeshes) g.visible = false;
817:   if (!p) return;
818:   const shape = SHAPES[p.type][p.rot];
819:   for (let i = 0; i < 4; i++) {
820:     const m = activeMeshes[i];
821:     m.visible = true;
822:     m.material = pieceMats[p.type];
823:     const [cx, cy] = shape.cells[i];
824:     m.position.set(p.x + cx - (W - 1) / 2, p.y + cy + 0.5, 0);
825:   }
826:   // ghost landing
827:   let gy = p.y;
828:   while (!collides(p.type, p.rot, p.x, gy - 1)) gy--;
829:   if (gy !== p.y) {
830:     for (let i = 0; i < 4; i++) {
831:       const g = ghostMeshes[i];
832:       g.visible = true;
833:       const [cx, cy] = shape.cells[i];
834:       g.position.set(p.x + cx - (W - 1) / 2, gy + cy + 0.5, 0);
835:     }
836:   }
837: }
838: 
839: function collides(type, rot, x, y) {
840:   const shape = SHAPES[type][rot];
841:   for (const [cx, cy] of shape.cells) {
842:     const bx = x + cx;
843:     const by = y + cy;
844:     if (bx < 0 || bx >= W || by < 0) return true;
845:     if (by < H && state.cells[by][bx]) return true;
846:   }
847:   return false;
848: }
849: 
850: function nextType() {
851:   if (!state.bag.length) {
852:     state.bag = Object.keys(PIECE_COLORS);
853:     for (let i = state.bag.length - 1; i > 0; i--) {
854:       const j = (Math.random() * (i + 1)) | 0;
855:       [state.bag[i], state.bag[j]] = [state.bag[j], state.bag[i]];
856:     }
857:   }
858:   return state.bag.pop();
859: }
860: 
861: function fillQueue() {
862:   while (state.queue.length < 4) state.queue.push(nextType());
863: }
864: 
865: function spawnPiece() {
866:   if (state.status !== 'playing') return;
867:   fillQueue();
868:   const type = state.queue.shift();
869:   fillQueue();
870:   const shape = SHAPES[type][0];
871:   const p = {
872:     type, rot: 0,
873:     x: Math.floor((W - shape.width) / 2),
874:     y: H - shape.height - 1
875:   };
876:   state.piece = p;
877:   state.canHold = true;
878:   state.dropTimer = 0;
879:   state.lockTimer = 0;
880:   updateActive();
881:   updateNextUI();
882:   updateHoldUI();
883:   if (collides(type, 0, p.x, p.y)) {
884:     state.piece = p;
885:     updateActive();
886:     endGame();
887:   }
888: }
889: 
890: function tryMove(dx, dy) {
891:   const p = state.piece;
892:   if (!p || state.clearing || state.status !== 'playing') return false;
893:   if (!collides(p.type, p.rot, p.x + dx, p.y + dy)) {
894:     p.x += dx;
895:     p.y += dy;
896:     state.lockTimer = 0;
897:     updateActive();
898:     return true;
899:   }
900:   return false;
901: }
902: 
903: function moveHorizontal(dir) {
904:   if (tryMove(dir, 0)) sound.move();
905: }
906: 
907: function rotatePiece(dir = 1) {
908:   const p = state.piece;
909:   if (!p || state.clearing || state.status !== 'playing') return;
910:   const nr = (p.rot + (dir > 0 ? 1 : 3)) % 4;
911:   const kicks = [[0, 0], [-1, 0], [1, 0], [-2, 0], [2, 0], [0, 1], [0, -1]];
912:   for (const [kx, ky] of kicks) {
913:     if (!collides(p.type, nr, p.x + kx, p.y + ky)) {
914:       p.rot = nr;
915:       p.x += kx;
916:       p.y += ky;
917:       state.lockTimer = 0;
918:       updateActive();
919:       sound.rotate();
920:       return;
921:     }
922:   }
923: }
924: 
925: function softDrop() {
926:   if (state.status !== 'playing' || state.clearing) return;
927:   if (tryMove(0, -1)) {
928:     state.score += 1;
929:     updateHUD();
930:     sound.softDrop();
931:   }
932: }
933: 
934: function hardDrop() {
935:   const p = state.piece;
936:   if (!p || state.clearing || state.status !== 'playing') return;
937:   let distance = 0;
938:   while (tryMove(0, -1)) distance++;
939:   state.score += distance * 2;
940:   updateHUD();
941:   sound.hardDrop();
942:   addShake(0.16);
943:   lockPiece();
944: }
945: 
946: function holdPiece() {
947:   if (state.status !== 'playing' || state.clearing || !state.canHold) return;
948:   const p = state.piece;
949:   if (!p) return;
950:   const old = state.hold;
951:   state.hold = p.type;
952:   state.canHold = false;
953:   if (old) {
954:     const shape = SHAPES[old][0];
955:     state.piece = {
956:       type: old, rot: 0,
957:       x: Math.floor((W - shape.width) / 2),
958:       y: H - shape.height - 1
959:     };
960:     state.dropTimer = 0;
961:     state.lockTimer = 0;
962:     updateActive();
963:     if (collides(state.piece.type, 0, state.piece.x, state.piece.y)) endGame();
964:   } else {
965:     state.piece = null;
966:     spawnPiece();
967:     state.canHold = false;
968:   }
969:   sound.hold();
970:   updateHoldUI();
971: }
972: 
973: function lockPiece() {
974:   const p = state.piece;
975:   if (!p) return;
976:   const shape = SHAPES[p.type][p.rot];
977:   for (const [cx, cy] of shape.cells) {
978:     const bx = p.x + cx;
979:     const by = p.y + cy;
980:     if (by >= 0 && by < H && bx >= 0 && bx < W) state.cells[by][bx] = { type: p.type };
981:   }
982:   state.piece = null;
983:   updateActive();
984:   updateBoard();
985:   sound.lock();
986:   const rows = [];
987:   for (let y = 0; y < H; y++) {
988:     if (state.cells[y].every(c => c)) rows.push(y);
989:   }
990:   if (rows.length) {
991:     beginClear(rows);
992:   } else {
993:     state.combo = 0;
994:     spawnPiece();
995:   }
996: }
997: 
998: function beginClear(rows) {
999:   const now = performance.now() / 1000;
1000:   state.clearing = true;
1001:   state.clearRows = rows;
1002:   state.clearTimer = 0;
1003:   state.clearStart = now;
1004:   state.combo++;
1005:   state.bestCombo = Math.max(state.bestCombo, state.combo);
1006:   const n = rows.length;
1007:   const base = [0, 100, 300, 500, 800][n] || 800;
1008:   const comboBonus = Math.max(0, state.combo - 1) * 50;
1009:   const gained = (base + comboBonus) * state.level;
1010:   state.score += gained;
1011:   for (const y of rows) {
1012:     for (let x = 0; x < W; x++) {
1013:       const cell = state.cells[y][x];
1014:       if (cell) cell.clearStart = now;
1015:       const pos = new THREE.Vector3(x - (W - 1) / 2, y + 0.5, 0);
1016:       boardGroup.localToWorld(pos);
1017:       sparks.burst(pos, PIECE_COLORS[cell?.type || 'I'], 3, { speed: 2.4, life: 0.7, spread: 0.55, up: 1.1 });
1018:     }
1019:   }
1020:   updateBoard(now);
1021:   updateHUD();
1022:   showCombo(n, gained);
1023:   addShake(0.3);
1024:   sound.clear(n);
1025: }
1026: 
1027: function finishClear() {
1028:   const rows = state.clearRows.slice().sort((a, b) => b - a);
1029:   for (const y of rows) state.cells.splice(y, 1);
1030:   while (state.cells.length < H) state.cells.unshift(Array(W).fill(null));
1031:   state.lines += rows.length;
1032:   state.level = 1 + Math.floor(state.lines / 5);
1033:   state.buildStage = Math.min(11, state.lines - 1);
1034:   state.clearing = false;
1035:   state.clearRows = [];
1036:   state.clearTimer = 0;
1037:   updateBoard();
1038:   updateHUD();
1039:   const stage = Math.min(11, state.buildStage);
1040:   if (stage >= 0) {
1041:     const before = cottage.stage;
1042:     cottage.setStage(stage, performance.now() / 1000);
1043:     if (cottage.stage > before) {
1044:       const p = cottage.getCenter();
1045:       sparks.burst(p, '#c8ff7a', 40, { speed: 4.2, life: 1.4, spread: 2.2, up: 2.2 });
1046:       sound.build();
1047:       toast(`Stage ${stage + 1} · ${STAGES[stage].name}`);
1048:       pulseBuild();
1049:     }
1050:   }
1051:   if (state.lines >= 12 && !state.celebrated) {
1052:     state.celebrated = true;
1053:     setTimeout(celebrate, 900);
1054:   } else {
1055:     spawnPiece();
1056:   }
1057: }
1058: 
1059: function addShake(amount) {
1060:   state.shake = Math.max(state.shake, amount);
1061:   state.shakeTime = 0.3;
1062: }
