1154: function updateCamera(dt, time) {
1155:   const portrait = window.innerHeight > window.innerWidth * 1.05 && window.innerWidth < 1000;
1156:   const menu = state.status === 'menu';
1157:   let pos, target, fov;
1158:   if (menu) {
1159:     if (portrait) {
1160:       pos = new THREE.Vector3(6.7 + Math.sin(time * 0.25) * 0.4, 9.2, 31);
1161:       target = new THREE.Vector3(6.15, 4.4, -1.2);
1162:       fov = 38;
1163:     } else {
1164:       pos = new THREE.Vector3(12.5 + Math.sin(time * 0.25) * 0.6, 9.6, 25.5);
1165:       target = new THREE.Vector3(5.8, 4.2, -1.4);
1166:       fov = 36;
1167:     }
1168:   } else if (portrait) {
1169:     pos = new THREE.Vector3(BOARD_X, 14.5, 43);
1170:     target = new THREE.Vector3(BOARD_X, 8.8, 0);
1171:     fov = 38;
1172:   } else {
1173:     pos = new THREE.Vector3(-2.5, 15.5, 39.5);
1174:     target = new THREE.Vector3(0.7, 8.4, 0);
1175:     fov = 36;
1176:   }
1177:   const k = 1 - Math.exp(-4.2 * dt);
1178:   camera.position.lerp(pos, k);
1179:   camera.userData.target = camera.userData.target || target.clone();
1180:   camera.userData.target.lerp(target, k);
1181:   camera.fov = lerp(camera.fov, fov, k);
1182:   camera.updateProjectionMatrix();
1183:   const look = camera.userData.target.clone();
1184:   if (state.shake > 0.001) {
1185:     const s = state.shake;
1186:     look.x += (Math.random() - 0.5) * s;
1187:     look.y += (Math.random() - 0.5) * s * 0.6;
1188:     camera.position.x += (Math.random() - 0.5) * s * 0.3;
1189:   }
1190:   camera.lookAt(look);
1191: }
